import {setGameLayout} from './mobile-game.js';
import {opponentFor} from './opponents.js';
import {CombatDirector,romanSoldier,paintCombat,combatHealth,combatHealthMarkup,updateCombatHealth} from './combat.js';
import {AnswerReveal,answerRevealMarkup} from './answer-reveal.js';
import {JourneyDirector,locationFor,symbolicGate,gateProgress} from './adventure.js';
import {judah,judahJourney} from './mascot.js';
import {questions,scriptureReference,difficultyCounts} from './questions.js';
import {createRun,submit,advance,nextLevel,rankFor,rankLabel,levelConfig,usePower,achievements,retryLevel,canRetryLevel} from './engine.js';
import {loadProfile,saveProfile,captureProgress,localScores,cleanNickname} from './storage.js';
import {ArcadeAudio} from './audio.js';
import {GameJuice} from './juice.js';
import {landscape,sword,environments} from './art.js';
const $=s=>document.querySelector(s),app=$('#app'),audio=new ArcadeAudio({onState:state=>{const control=$('#sound');if(control){control.dataset.audioState=state.state;control.dataset.playCount=state.playCount;if(state.effect)control.dataset.lastEffect=state.effect;}}}),juice=new GameJuice(app),letters=['A','B','C','D'];
let storage;try{storage=window.localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Unavailable')}}}
let profile=loadProfile(storage,questions),run=profile.run,view='title',paused=false,deadline=0,timer=null,lastSavedSecond=-1,filter='all',env=0,storageOK=true;
const combat=new CombatDirector(),director=new JourneyDirector(),answerReveal=new AnswerReveal(document);
let pendingCombatHUD=null;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>Math.floor(n).toLocaleString('en-US');
const button=(label,action,cls='button',disabled=false)=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
function persist(){if(run)captureProgress(profile,run);storageOK=saveProfile(storage,profile);const msg=$('#storage-warning');if(msg)msg.hidden=storageOK;}
function music(){audio.configure(profile.settings.sound,profile.settings.music,view==='game'&&!paused&&run?.status==='playing'||view==='title'||view==='journey'&&!document.hidden)}
function stopClock(){clearInterval(timer);timer=null;deadline=0}
function clock(){if(view!=='game'||paused||run?.status!=='playing')return;run.remaining=Math.max(0,(deadline-Date.now())/1000);const seconds=Math.ceil(run.remaining);$('.question-panel')?.classList.toggle('time-urgent',seconds<=10);if($('#clock')){$('#clock').textContent=String(seconds).padStart(2,'0');$('#clock').classList.toggle('danger',seconds<=10)}if($('#time-fill'))$('#time-fill').style.width=`${Math.min(100,run.remaining/levelConfig(run.level).seconds*100)}%`;if(seconds!==lastSavedSecond){lastSavedSecond=seconds;persist()}if(run.remaining===0)choose(-1);}
function startClock(){stopClock();if(view!=='game'||paused||run?.status!=='playing')return;deadline=Date.now()+run.remaining*1000;timer=setInterval(clock,150)}
function setView(next){director.cancel();stopClock();view=next;paused=false;render();startClock();music();window.scrollTo({top:0,behavior:'instant'})}
function retry(){if(!retryLevel(run,questions))return;persist();audio.unlock();audio.effect('start');setView('game');juice.enter('question')}
function start(){if(run&&run.status!=='gameover'&&!confirm('Start a new run? Your saved run will be replaced.'))return;profile.nickname=cleanNickname($('#nickname')?.value||profile.nickname);run=createRun(questions,profile.nickname);persist();audio.unlock();audio.effect('start');setView('game')}
function choose(choice){
 if(!run||paused||run.status!=='playing'||combat.active)return;
 if(deadline&&Date.now()>=deadline)choice=-1;
 stopClock();const before={score:run.score,lives:run.lives,streak:run.streak,hits:combatHealth(run).hits};if(!submit(run,questions,choice))return;
 pendingCombatHUD=before;
 const last=run.answers.at(-1);persist();render(true);music();
 combat.start({correct:last.correct,enemyDefeated:combatHealth(run).enemy===0,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,
  onFrame:frame=>paintCombat($('.game-scene'),frame,run.completed),
  onImpact:()=>{
   pendingCombatHUD=null;
   updateCombatHealth($('.combat-health'),run);
   // Commit the visual reward/penalty at impact; the engine and save already own the result.
   const template=document.createElement('template');template.innerHTML=hud();$('.hud')?.replaceWith(template.content.firstElementChild);
   if(last.correct){audio.effect('swordStrike');audio.effect('correct',.18)}else audio.effect(last.shielded?'shield':'damage');
   if(!last.correct&&!last.shielded)audio.effect('lifeLost',.2);
   juice.answer({...last,score:run.score,streak:run.streak});
   juice.burst($('.combat-sparks'),16,last.correct?'gold':'green');
   if(last.correct&&levelConfig(run.level).boss)juice.burst($('.symbolic-gate'),12,'gold');
  },
  onFinish:()=>{if($('#answer-reveal'))answerReveal.open($('#answer-reveal'),proceed)}
 });
}
function proceed(){if(combat.active||!run||run.status!=='feedback')return;advance(run,questions);persist();render();startClock();music();if(run.status==='levelup'){const perfect=run.answers.every(a=>a.correct);audio.effect(perfect?'perfectVictory':run.lastPromotion?'promotion':'levelComplete');if(levelConfig(run.level).boss)audio.effect('gateOpen',.15)}else audio.effect(run.status==='gameover'?'gameover':'next');juice.enter(run.lastPromotion&&run.status==='levelup'?'promotion':'question');if(run.status==='levelup'&&(run.lastPromotion||run.answers.every(a=>a.correct)))juice.burst($('.result-adventure'),24,'gold');$('#screen-title')?.focus()}
function finishJourney(){if(!run||run.status!=='levelup')return;director.cancel();nextLevel(run,questions);view='game';paused=false;persist();render();startClock();music();audio.effect(levelConfig(run.level).boss?'gatekeeper':'next');juice.enter();$('#screen-title')?.focus()}
function beginJourney(){if(!run||run.status!=='levelup'||director.active)return;stopClock();if(profile.settings.shortJourneys||matchMedia('(prefers-reduced-motion: reduce)').matches)return finishJourney();view='journey';paused=false;render();music();$('#skip-journey')?.focus();director.start({onPhase:phase=>{const screen=$('.journey-screen');if(!screen)return;screen.dataset.phase=phase.name;$('.journey-hero').innerHTML=judah(run.completed,phase.pose,false);if(phase.name==='arrival')audio.effect((run.level+1)%5===0?'gatekeeper':'select');},onFinish:finishJourney})}
function journeyScreen(){const next=run.level+1,[slug,name]=locationFor(next);return `<section class="journey-screen" data-phase="walk"><p class="kicker">THE NEXT GATE AWAITS</p><h1 id="screen-title" tabindex="-1">${name}</h1><div class="journey-canvas" aria-label="Judah journeys toward the next Scripture challenge"><div class="journey-plane journey-sky" style="background-image:url('assets/console/journey-${slug}-sky.png')"></div><div class="journey-plane journey-far" style="background-image:url('assets/console/journey-${slug}-far.png')"></div><div class="journey-plane journey-near" style="background-image:url('assets/console/journey-${slug}-near.png')"></div><div class="journey-destination">${symbolicGate()}</div><div class="journey-hero">${judah(run.completed,'walk',false)}</div><div class="journey-intro"><b>LEVEL ${next}</b><span>${next%5===0?'GATEKEEPER CHALLENGE':'NEXT OPPONENT'} · ${opponentFor(next).name}</span></div></div><p class="journey-caption">A brief journey between Scripture challenges. Your question timer has not started.</p>${button('SKIP JOURNEY →','skip-journey','button primary').replace('<button','<button id="skip-journey"')} ${button('TURN OFF FUTURE JOURNEYS','transitions','menu-link')}<p class="fine-print">Escape skips. Journeys pause while this tab is hidden.</p></section>`}
function pause(){if(view!=='game'||paused||run?.status==='feedback')return;if(run.status==='playing'&&deadline)run.remaining=Math.max(0,(deadline-Date.now())/1000);stopClock();paused=true;persist();render();music();if(!document.hidden)audio.effect('pause');$('#resume-button')?.focus()}
function resume(){paused=false;render();startClock();music();audio.effect('resume');juice.enter()}
function power(type){if(deadline)run.remaining=Math.max(0,(deadline-Date.now())/1000);if(!usePower(run,questions,type))return;audio.effect('power');persist();render();startClock()}
function retire(){if(!confirm('End this run and record its current score on this device?'))return;stopClock();run.status='gameover';run.endedAt=new Date().toISOString();paused=false;persist();render();music();audio.effect('gameover')}
function activeEnvironment(){const unlocked=environments.filter(e=>profile.bestCompleted>=e.unlock);return Math.min(env,unlocked.length-1)}
function hud(){const shown=pendingCombatHUD||run,rank=rankFor(run.completed),mult=Math.min(5,1+Math.floor(shown.streak/3));return `<div class="hud"><div><small>PLAYER</small><strong>${esc(run.nickname)}</strong></div><div><small>SCORE</small><strong id="score-value" class="gold">${number(shown.score).padStart(6,'0')}</strong></div><div><small>LEVEL</small><strong>${String(run.level).padStart(2,'0')}</strong></div><div><small>LIVES</small><strong class="hearts" aria-label="${shown.lives} lives remaining">${'♥'.repeat(shown.lives)}<span>${'♡'.repeat(3-shown.lives)}</span></strong></div><div><small>STREAK ${shown.streak}</small><strong class="cyan hud-combo">×${mult}</strong></div></div><div class="rank-strip"><span>✦ ${esc(rankLabel(rank))}</span><span>${rank.next-(run.completed+1)} level${rank.next-(run.completed+1)===1?'':'s'} to promotion</span><progress aria-label="Progress to next promotion" value="${run.completed+1-rank.start}" max="${rank.next-rank.start}"></progress>${button('Ⅱ PAUSE','pause','tiny')}</div>`}
function titleScreen(){const rank=rankFor(profile.bestCompleted);return `<section class="title-screen"><div class="broadcast"><i></i> ARCADE EDITION <span>EST. IN THE WORD • VOL. 02</span></div><div class="title-art">${landscape(activeEnvironment())}${judah(profile.bestCompleted)}<div class="floating-sword">${sword}</div><div class="title-logo"><p>LIONS GATE</p><h1>SWORD<br><span>SHARPENER</span></h1><div class="logo-sub">THE SCRIPTURE ARCADE</div></div><span class="art-caption">${environments[activeEnvironment()].name.toUpperCase()}</span></div><div class="title-menu"><p class="intro-line">Three lives. Endless levels. One sharp mind.</p><label class="nickname-label" for="nickname">PLAYER NAME <input id="nickname" maxlength="16" autocomplete="nickname" value="${esc(profile.nickname)}" spellcheck="false"></label>${button('▶ &nbsp; PRESS START','start','button primary press-start')}${canRetryLevel(run)?button(`RETRY · LEVEL ${run.level}`,'retry-level','button continue'):run&&run.status!=='gameover'?button(`CONTINUE · LEVEL ${run.level}`,'continue','button continue'):''}<div class="menu-links">${button('HALL OF MASTERS','hall','menu-link')}${button('HOW TO PLAY','guide','menu-link')}${button('THE ARMORY','armory','menu-link')}</div><div class="personal-bar"><span>PERSONAL BEST <b>${number(profile.bestScore)}</b></span><span>HIGHEST RANK <b>${esc(rankLabel(rank))}</b></span><span>LEVELS CLEARED <b>${profile.bestCompleted}</b></span></div></div></section>`}
function questionScreen(){const entry=run.queue[run.index],q=questions.find(q=>q.id===entry.id),config=levelConfig(run.level),feedback=run.status==='feedback',last=run.answers.at(-1),gate=gateProgress(run);return `${hud()}${combatHealthMarkup(run,pendingCombatHUD)}<div class="game-scene ${config.boss?'boss-scene adventure-arena':''}">${landscape(Math.min(environments.length-1,environments.filter(e=>run.completed>=e.unlock).length-1))}${config.boss?symbolicGate(gate):''}<div class="scene-status"><span>${config.boss?'⚔ GATEKEEPER CHALLENGE':'✦ LEVEL '+run.level} <b>${config.boss?'DOUBLE POINTS · CONTEXT CHALLENGE':'THE WORD IS YOUR WEAPON'}</b></span>${judah(run.completed,'ready',false)}${romanSoldier(combatHealth(run,pendingCombatHUD).enemy===0)}<span class="combat-sparks" aria-hidden="true"></span><div class="small-sword">${sword}</div>${config.boss?`<div class="boss-health" aria-label="${10-gate.broken} gate seals remaining"><span>SEALS SHATTERED ${gate.broken} / 10</span><div>${Array.from({length:10},(_,i)=>`<i class="${i<gate.broken?'broken':''} ${feedback&&last.correct&&i===gate.broken-1?'breaking':''}"></i>`).join('')}</div></div>`:''}</div></div><section class="question-panel"><div class="question-meta"><span>QUESTION ${run.index+1} / 10 <b>• ${esc(q.category)}</b>${q.trapType?` <em class="trap-label">${q.trapType.toUpperCase()} TRAP</em>`:''}</span><span class="difficulty">${'◆'.repeat(q.difficulty)}${'◇'.repeat(3-q.difficulty)} <span>${['','FOUNDATION','CHALLENGER','CONTEXT'][q.difficulty]}</span></span><span class="clock">◷ <b id="clock">${Math.ceil(run.remaining)}</b>s</span></div><div class="time-track"><div id="time-fill" style="width:${Math.min(100,run.remaining/config.seconds*100)}%"></div></div><h1 id="screen-title" tabindex="-1">${esc(q.q)}</h1><div class="answers">${entry.order.map((original,i)=>{const hidden=run.eliminated.includes(original);return `<button class="answer ${feedback?(original===q.answer?'correct':original===last.choice?'wrong':'dim'):''} ${hidden?'eliminated':''}" data-answer="${original}" ${feedback||hidden?'disabled':''}><span>${letters[i]}</span><strong>${hidden?'— — —':esc(q.options[original])}</strong><b>${feedback&&original===q.answer?'✓':feedback&&original===last.choice?'×':''}</b></button>`}).join('')}</div><div class="power-row"><span>POWER-UPS <small>LIMITED PER RUN</small></span>${button(`◈ 50:50 <b>${run.powers.fifty}</b>`,'fifty','power',feedback||!run.powers.fifty||run.eliminated.length>0)}${button(`◷ +15s <b>${run.powers.time}</b>`,'time','power',feedback||!run.powers.time)}${button(`⬡ SHIELD <b>${run.powers.shield}</b>`,'shield','power',feedback||!run.powers.shield||run.shielded)}</div><p class="controls-hint">${run.shielded?'⬡ SHIELD ACTIVE · THE NEXT MISTAKE IS PROTECTED':'CHOOSE AN ANSWER · A–D OR 1–4 · P TO PAUSE'}</p></section>${feedback?answerRevealMarkup({q,last,streak:run.streak,continuation:run.lives<=0?'VIEW RUN RESULTS':run.index===9?'LEVEL COMPLETE':'NEXT QUESTION'}):''}`}
function reviewList(){return `<details class="review-list"><summary>REVIEW THIS LEVEL ↓</summary>${run.answers.map(a=>{const q=questions.find(q=>q.id===a.id);return `<article><span>${a.correct?'✓':'×'} ${esc(q.category)}</span><h3>${esc(q.q)}</h3><p>Your answer: ${a.choice===-1?'Time expired':esc(q.options[a.choice])}</p><p>Correct answer: <strong>${esc(q.correctAnswer)}</strong></p><p>${esc(q.explain)}</p><a href="${q.scripture.url}" target="_blank" rel="noopener noreferrer">${scriptureReference(q)} ↗</a></article>`}).join('')}</details>`}
function resultScreen(){const cleared=run.status==='levelup',perfect=cleared&&run.answers.every(a=>a.correct),rank=rankFor(run.completed),promotion=run.lastPromotion;return `${hud()}<section class="result-screen ${cleared?'victory':''} ${canRetryLevel(run)?'retry-result':''}"><div class="confetti" aria-hidden="true">${Array.from({length:16},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="result-emblem">${sword}</div><div class="result-adventure ${perfect?'perfect-victory':''} ${promotion?'rank-transformation':''}">${cleared&&levelConfig(run.level).boss?symbolicGate({broken:run.answers.filter(a=>a.correct).length,open:true}):''}${judah(run.completed,promotion?'transform':cleared?'victory':'recoil')}</div><p class="kicker">${promotion?'RANK PROMOTION':cleared?'THE GATE IS OPEN':canRetryLevel(run)?'THE GATE AWAITS YOUR RETURN':'YOUR RUN IS COMPLETE'}</p><h1 id="screen-title" tabindex="-1">${promotion?esc(promotion):cleared?'LEVEL '+run.level+' CLEARED':'GAME OVER'}</h1><p class="result-sub">${cleared?perfect?`PERFECT LEVEL! +${number(levelConfig(run.level).bonus)} BONUS`:'Well played. The next gate awaits.':canRetryLevel(run)?`Retry Level ${run.level} with three lives. Your earned points and rank are kept. Retry points count only beyond this level’s previous best attempt.`:'Every run is a chance to sharpen your understanding.'}</p>${canRetryLevel(run)?`<div class="retry-actions">${button('RETRY LEVEL ↻','retry-level','button primary')}${button('NEW GAME','new-run','button')}</div>`:''}<div class="result-stats"><div><small>SCORE</small><strong>${number(run.score)}</strong></div><div><small>LEVELS CLEARED</small><strong>${run.completed}</strong></div><div><small>BEST STREAK</small><strong>${run.bestStreak}</strong></div></div><p class="rank-label">✦ ${esc(rankLabel(rank))} · ${run.lives} ${run.lives===1?'LIFE':'LIVES'} REMAINING</p><div class="earned-badges">${achievements(run).map(b=>`<span>✧ ${b}</span>`).join('')}</div>${cleared?button(`ENTER LEVEL ${run.level+1} →`,'next-level','button primary'):canRetryLevel(run)?'':button('NEW GAME','new-run','button')}<div class="menu-links">${button('TITLE SCREEN','title','menu-link')}${button('HALL OF MASTERS','hall','menu-link')}</div>${reviewList()}</section>`}
function hallScreen(){const sample=filter==='sample';const rows=sample?[{id:'demo1',nickname:'DEMO_01',score:125000,completed:61,level:62},{id:'demo2',nickname:'DEMO_02',score:91000,completed:51,level:52},{id:'demo3',nickname:'DEMO_03',score:64000,completed:32,level:33}]:localScores(profile,filter);return `<section class="menu-screen"><p class="kicker">RECORDS OF THE SHARP</p><h1>HALL OF <span>MASTERS</span></h1><div class="local-badge">${sample?'◇ ONLINE DEMO · FICTIONAL SAMPLE RECORDS':'● THIS DEVICE ONLY · NOT A GLOBAL LEADERBOARD'}</div><div class="hall-tabs">${button('ALL TIME','all',`tab ${filter==='all'?'active':''}`)}${button('THIS WEEK','week',`tab ${filter==='week'?'active':''}`)}${button('ONLINE DEMO','sample',`tab ${sample?'active':''}`)}</div><div class="table-wrap"><table><thead><tr><th>#</th><th>PLAYER</th><th>SCORE</th><th>LEVEL REACHED</th><th>MASTER DEGREE</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td>${esc(cleanNickname(r.nickname))}</td><td>${number(r.score)}</td><td>${r.level||r.completed+1}</td><td>${rankFor(r.completed).degree||'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-state">NO COMPLETED RUNS YET<br><small>Your next run could set the first record.</small></td></tr>'}</tbody></table></div><p class="fine-print">Completed runs only. Score descending, then completed levels descending, then earliest finish, then run ID. Weekly window begins Monday 00:00 UTC. Records stay in this browser and can be edited or cleared by its user.</p><div class="online-panel"><span>ONLINE RANKINGS</span><h2>The worldwide hall is not connected.</h2><p>Global competition needs accounts, server-owned run sessions, and server-side answer and score validation. Local scores are not submitted as trusted global scores.</p></div>${button('← BACK TO TITLE','title','button')}</section>`}
function guideScreen(){return `<section class="menu-screen"><p class="kicker">PLAYER’S MANUAL</p><h1>KNOW THE <span>RULES.</span></h1><div class="manual-grid"><article><b>01 / SURVIVE THE RUN</b><p>Start with three lives. Each level has ten questions. Wrong answers and expired timers cost one life. Read the explanation before continuing; its timer is stopped.</p></article><article><b>02 / BUILD YOUR STREAK</b><p>Correct answers start at 100 points. The multiplier rises every three consecutive correct answers, up to ×5. A mistake resets the streak. Boss levels double answer points. A perfect level adds 500 + 50 × level points.</p></article><article><b>03 / MASTER THE GATES</b><p>Level 1 draws foundation questions. Levels 2–4 add challenger questions. Level 5 onward includes context questions and closer distractors. Every fifth level is a Gatekeeper round, prioritizing Tradition, Context, and Misquote Traps. Harder questions get more reading time, not less.</p></article><article><b>04 / USE YOUR ARMORY</b><p>Per run: three 50:50 uses, two +15-second boosts, and one shield. The shield protects one question from life loss, but a wrong answer still breaks your streak. Pause freezes the clock. Hiding the tab pauses automatically.</p></article></div><h2>Ranks are earned by clearing levels.</h2><p>Novice: levels 1–5. Student: 6–15. Scholar: 16–30. Scribe: 31–50. Master 1st Degree: 51–60. Each further ten levels adds a degree, without a programmed level cap. Clearing level 5 unlocks level 6 and the Student rank; points never buy promotions.</p><h2>Scripture is the answer authority.</h2><p>The traditional 80-book KJV collection includes 39 Old Testament, 27 New Testament, and 14 Apocrypha books. Baruch includes the Letter of Jeremiah; the Song of the Three Holy Children includes the Prayer of Azariah. Tradition, Context, and Misquote Traps test the cited text respectfully. Each level targets seven questions about commandments, Torah, Sabbath, feast days, clean and unclean, obedience, or contextual reading, plus three general questions. It seeks two traps, or three at Gatekeeper levels, as the eligible pool permits.</p><div class="bank-counts">${difficultyCounts.map(d=>`<div><strong>${d.count}</strong><span>${['','FOUNDATION','CHALLENGER','CONTEXT'][d.difficulty]}</span></div>`).join('')}</div><p class="fine-print">${questions.length} passage-reviewed questions in this release. No unverified question generation. Each level uses ten distinct questions. Approved questions use least-seen, least-recent spaced repetition within the focus and general pools; answer positions are shuffled. Content difficulty has three tiers and plateaus at the highest tier.</p>${button('← BACK TO TITLE','title','button')}</section>`}
function armoryScreen(){return `<section class="menu-screen"><p class="kicker">YOUR LONG-TERM COLLECTION</p><h1>THE <span>ARMORY</span></h1><p>Unlock environments and badges through completed levels and skilled play. Saved on this device.</p><div class="environment-grid">${environments.map((e,i)=>{const unlocked=profile.bestCompleted>=e.unlock;return `<article class="environment-card ${unlocked?'':'locked'}">${landscape(i)}<h2>${e.name}</h2><p>${unlocked?'UNLOCKED':`CLEAR ${e.unlock} LEVELS`}</p>${button(unlocked?(env===i?'SELECTED':'TITLE BACKDROP'):'LOCKED',`env-${i}`,'tiny',!unlocked)}</article>`}).join('')}</div>${judahJourney(profile.bestCompleted)}${button(`JOURNEYS ${profile.settings.shortJourneys?'OFF':'FULL'} · CHANGE`,'transitions','button')}<p class="fine-print">Four-second journeys are skippable. Turning them off enters the next level immediately. Your system’s reduced-motion preference also skips them.</p><h2>Achievement badges</h2><div class="badge-grid">${[['First Strike','Answer one question correctly'],['On Fire','Reach a streak of five'],['Flawless','Clear a perfect level'],['Gatekeeper','Clear a fifth-level challenge'],['Student','Clear five levels'],['Master','Clear fifty levels']].map(([name,desc])=>`<article class="${profile.badges.includes(name)?'unlocked':''}"><span>${profile.badges.includes(name)?'✦':'◇'}</span><b>${name}</b><small>${desc}</small></article>`).join('')}</div>${button('← BACK TO TITLE','title','button')}</section>`}
function pauseScreen(){return `<div class="pause-overlay" role="dialog" aria-modal="true" aria-label="Game paused"><section><p class="kicker">TAKE A BREATH</p><h1>PAUSED</h1><p>Your clock is frozen. Your run is saved on this device.</p>${button('▶ RESUME','resume','button primary').replace('<button','<button id="resume-button"')}<div class="menu-links">${button('SAVE & TITLE','save-title','menu-link')}${button('END RUN','retire','menu-link')}</div></section></div>`}
function updateAudioControls(){$('#sound').textContent=`SFX ${profile.settings.sound?'ON':'OFF'}`;$('#sound').setAttribute('aria-pressed',profile.settings.sound);$('#music').textContent=`MUSIC ${profile.settings.music?'ON':'OFF'}`;$('#music').setAttribute('aria-pressed',profile.settings.music);}
function render(deferReveal=false){
 combat.cancel();
 if(!deferReveal)pendingCombatHUD=null;
 answerReveal.close();
 juice.clear();
 updateAudioControls();
 app.innerHTML=view==='journey'?journeyScreen():view==='title'?titleScreen():view==='hall'?hallScreen():view==='guide'?guideScreen():view==='armory'?armoryScreen():run?.status==='levelup'||run?.status==='gameover'?resultScreen():questionScreen();
 setGameLayout(view==='game'&&['playing','feedback'].includes(run?.status));
 if(paused)app.insertAdjacentHTML('beforeend',pauseScreen());
 app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.answer)));
 app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));
 if($('#nickname'))$('#nickname').addEventListener('change',e=>{profile.nickname=cleanNickname(e.target.value);e.target.value=profile.nickname;persist()});
 $('#storage-warning').hidden=storageOK;
 if($('#answer-reveal')&&!paused&&!deferReveal)answerReveal.open($('#answer-reveal'),proceed);
}
function act(action){audio.unlock();if(['title','hall','guide','armory','all','week','sample','save-title','continue'].includes(action)||action.startsWith('env-'))audio.effect('select');if(action==='retry-level')return retry();if(action==='start'||action==='new-run')return start();if(action==='continue'){view='game';paused=run.status==='playing';render();music();return}if(action==='next')return proceed();if(action==='next-level')return beginJourney();if(action==='skip-journey')return director.finish();if(action==='transitions'){profile.settings.shortJourneys=!profile.settings.shortJourneys;persist();if(view==='journey'&&profile.settings.shortJourneys)return director.finish();render();return}if(action==='pause')return pause();if(action==='resume')return resume();if(action==='retire')return retire();if(action==='save-title'){persist();return setView('title')}if(action==='title')return setView('title');if(['hall','guide','armory'].includes(action))return setView(action);if(['all','week','sample'].includes(action)){filter=action;render();return}if(['fifty','time','shield'].includes(action))return power(action);if(action.startsWith('env-')){env=Number(action.slice(4));render()}}
$('#sound').onclick=()=>{audio.unlock();profile.settings.sound=!profile.settings.sound;music();audio.effect('select');persist();if(view!=='journey'&&!combat.active)render();else updateAudioControls()};$('#music').onclick=()=>{audio.unlock();profile.settings.music=!profile.settings.music;persist();if(view!=='journey'&&!combat.active)render();else updateAudioControls();music();audio.effect('select')};
$('#brand').onclick=e=>{e.preventDefault();if(view==='game'&&run?.status==='playing')pause();else setView('title')};
document.addEventListener('keydown',e=>{if($('#answer-reveal')?.open){if(e.repeat&&['Enter','Escape'].includes(e.key)){e.preventDefault();return}if(e.key==='Escape'){e.preventDefault();proceed()}return}if(view==='journey'&&e.key==='Escape'){e.preventDefault();return director.finish()}if(paused&&e.key==='Tab'){const controls=[...document.querySelectorAll('.pause-overlay button')];const at=controls.indexOf(document.activeElement);e.preventDefault();controls[(at+(e.shiftKey?-1:1)+controls.length)%controls.length]?.focus();return}if(e.repeat||['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(view==='game'&&(e.key.toLowerCase()==='p'||e.key==='Escape')){e.preventDefault();return paused?resume():pause()}if(view==='title'&&e.key==='Enter'&&!['BUTTON','A'].includes(e.target.tagName))return start();if(view==='game'&&!paused&&run?.status==='playing'){const i=letters.indexOf(e.key.toUpperCase())>=0?letters.indexOf(e.key.toUpperCase()):Number(e.key)-1;if(Number.isInteger(i)&&i>=0&&i<4){const original=run.queue[run.index].order[i];if(!run.eliminated.includes(original))choose(original)}}});
document.addEventListener('visibilitychange',()=>{if(view==='journey'){document.hidden?director.pause():director.resume();$('.journey-screen')?.classList.toggle('journey-paused',document.hidden);music()}else if(document.hidden&&view==='game')pause()});
window.addEventListener('pagehide',()=>{if(run?.status==='playing'&&deadline)run.remaining=Math.max(0,(deadline-Date.now())/1000);persist()});
audio.configure(profile.settings.sound,false,false);
render();
